head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactTpCd = '';
scwin.vTempRsn = '';
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 숨기기
        txb_BndListProcsTpCd.hide();
        // 호출파라미터설정
        scwin.setParam();
        // 상호변경에서 호출 시, 한글기준명 숨기기
        scwin.hideIsuNm();

        // 데이터셋정의

        // dts_Return.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_Return.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90004.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90004.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Return_onclick
 * @description 「반송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Return_onclick = async function() {
    try {
        if (txb_BndApplId.getValue() === "") return;
        if (txa_RetRsn.getValue().length === 0) {
            await $c.win.alert("반송 사유를 입력하십시오");
            txa_RetRsn.focus();
            return;
        }
        if (txa_RetRsn.getValue().length > 20) {
            await $c.win.alert("반송 사유를 20자 이내로 입력하십시오.");
            txa_RetRsn.focus();
            return;
        }
        if (!window.confirm("반송처리 하시겠습니까?")) return;
        scwin.return();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90004.btn_Return_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90004.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert('[반송]처리 성공하였습니다.');
        let arrPar = new Array();
        arrPar[0] = {
            SUCCESS_YN: 'Y'
        };

        // var parentFrame = frame.Provider("../");
        scwin.fn_SetPar(arrPar);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90004.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name rdo_RetCd_onclick
 * @description rdo_RetCd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_RetCd_onclick = function() {
    try {
        const retRsn = txa_RetRsn.getValue();
        const rdoCd = rdo_RetCd.getValue();
        txa_RetRsn.setValue('');
        let rdoText = '';
        if (rdoCd === '1') {
            rdoText = '중복신청';
        } else if (rdoCd === '2') {
            rdoText = '신청자요청';
        } else if (rdoCd === '3') {
            rdoText = '기재내용 오류';
        } else if (rdoCd === '4') {
            rdoText = '코드기부여';
        }
        txa_RetRsn.setValue(rdoText);
        /*
        if(retRsn != '') {
        	setObjectValue(txa_RetRsn, rdoText+'\n'+ retRsn);
        }else {
        	setObjectValue(txa_RetRsn, rdoText);
        }
         */
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90004.rdo_RetCd_onclick" });
    }
};

/**
 * @method
 * @name txa_RetRsn_onchange
 * @description txa_RetRsn 변경 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_RetRsn_onchange = async function() {
    try {
        const rsn = txa_RetRsn.getValue();
        if (rsn === '') return;
        if (rsn.length > 20) {
            await $c.win.alert("반송 사유를 20자 이내로 입력하십시오.");
            txa_RetRsn.setValue('');
            txa_RetRsn.setValue(scwin.vTempRsn);
        } else {
            scwin.vTempRsn = rsn;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90004.txa_RetRsn_onchange" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name return
 * @description 신청 및 접수 데이터를 반송처리한다.
 * @returns {void}
 * @hidden N
 */
scwin.return = function() {
    let url = "/bns/BnsCommon.do?method=processApplAcptRet";
    url += "&SCREN_ID=" + "ULDBNS90004.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    let param = "BND_APPL_ID=" + txb_BndApplId.getValue();
    param += ", BND_LIST_PROCS_TP_CD=" + txb_BndListProcsTpCd.getValue();
    param += ", RET_RSN=" + txa_RetRsn.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Return)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        let arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        txb_BndApplId.setValue(arrPar[0].BND_APPL_ID);
        txb_BndListProcsTpCd.setValue(arrPar[0].BND_LIST_PROCS_TP_CD);
        txb_IsurNm.setValue(arrPar[0].ISUR_NM);
        txb_IsuNm.setValue(arrPar[0].ISU_NM);
        if (arrPar[0].MKTACT_TP_CD !== undefined) {
            scwin.vMktactTpCd = arrPar[0].MKTACT_TP_CD;
        }
    }
};

/**
 * @method
 * @name hideIsuNm
 * @description 상호변경에서 호출 시, 한글기준명 숨기기
 * @returns {void}
 * @hidden N
 */
scwin.hideIsuNm = function() {
    if (scwin.vMktactTpCd === '201') {
        lbl_IsuNm.hide();
        txb_IsuNm.hide();
        lbl_RetCd.style.top = '61px';
        rdo_RetCd.style.top = '61px';
        lbl_RetRsn.style.top = '87px';
        txa_RetRsn.style.top = '87px';
    }
};
